/* Процент карт с японским переводом, доступных только в non-foil */
SELECT
    /* Доля карт с isNonFoilOnly = 1 среди карт с японским переводом, в процентах */
    SUM(CASE WHEN c."isnonfoilonly" = 1 THEN 1 ELSE 0 END) * 100.0
