```sql
/* Доля карт без силы (power IS NULL или '*'), у которых язык — французский */
SELECT
    /* Процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(*) FILTER (
        WHERE fd."language" = 'French'
          AND (c."power" IS NULL OR c."power" = '*')
    )::numeric
    / NULLIF(COUNT(*) FILTER (
        WHERE c."power" IS NULL OR c."power" = '*'
    ), 0)) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd."uuid" = c."uuid"
WHERE c."power" IS NULL OR c."power" = '*';
```

