```sql
/* Находим минимальную репутацию среди пользователей */
WITH min_rep AS (
    SELECT MIN("reputation") AS min_reputation
    FROM "users"
),
/* Пользователи с минимальной репутацией */
lowest_users AS (
    SELECT "id"
    FROM "users", min_rep
    WHERE "reputation" = min_rep.min_reputation
)
/* Уникальные названия бейджей, полученных этими пользователями */
SELECT DISTINCT b."name"
FROM "badges" b
JOIN lowest_users lu ON b."userid" = lu."id"
ORDER BY b."name";
```

